create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create table public.users (id uuid primary key references auth.users(id) on delete cascade,email text unique not null,role text not null check(role in ('pencari','pemilik')));
create table public.listings (
 id bigint generated by default as identity primary key,owner_id uuid references public.users(id),name text not null,address text not null,
 price bigint not null check(price>0),latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),area double precision not null check(area>0),
 image text not null,facilities text not null default '[]',description text not null default '',status text not null check(status in ('draft','available','reserved','rented')),demo_json text,
 created_at text not null default to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),updated_at text not null default to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
create table public.listing_analyses (listing_id bigint primary key references public.listings(id) on delete cascade,model_version text not null,input_fingerprint text not null,analyzed_at text not null,result_json text not null);
create table public.favorites (user_id uuid not null references public.users(id) on delete cascade,listing_id bigint not null references public.listings(id) on delete cascade,primary key(user_id,listing_id));
create table public.wizard_drafts (user_id uuid primary key references public.users(id) on delete cascade,data text not null,updated_at text not null);
create table public.surveys (id uuid primary key default gen_random_uuid(),listing_id bigint not null references public.listings(id),seeker_id uuid not null references public.users(id),date text not null,time text not null,visitors integer not null check(visitors between 1 and 20),note text not null,status text not null check(status in ('pending','confirmed','rejected','cancelled')),owner_note text not null default '',created_at text not null,updated_at text not null);
create table public.applications (id uuid primary key default gen_random_uuid(),listing_id bigint not null references public.listings(id),seeker_id uuid not null references public.users(id),tenant_json text not null,start_date text not null,duration integer not null check(duration between 1 and 10),offer bigint not null check(offer>0),proposal text not null,status text not null check(status in ('pending','approved','rejected','withdrawn')),owner_note text not null default '',created_at text not null,updated_at text not null);
create table public.messages (id bigint generated by default as identity primary key,listing_id bigint not null references public.listings(id),seeker_id uuid not null references public.users(id),sender_id uuid not null references public.users(id),text text not null check(length(text) between 1 and 3000),created_at text not null default to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
create unique index one_pending_survey on public.surveys(listing_id,seeker_id) where status='pending';
create unique index one_confirmed_survey on public.surveys(listing_id,date,time) where status='confirmed';
create unique index one_open_application on public.applications(listing_id,seeker_id) where status in ('pending','approved');
create unique index one_approved_application on public.applications(listing_id) where status='approved';
create index listings_owner on public.listings(owner_id);
create index favorites_listing on public.favorites(listing_id);
create index surveys_seeker on public.surveys(seeker_id);
create index applications_seeker on public.applications(seeker_id);
create index messages_thread on public.messages(listing_id,seeker_id,id);
create index messages_seeker on public.messages(seeker_id);
create index messages_sender on public.messages(sender_id);
create function private.account_role() returns text language sql stable security definer set search_path='' as $$ select role from public.users where id=(select auth.uid()) $$;
revoke all on function private.account_role() from public;
grant execute on function private.account_role() to authenticated;
-- Role is copied once into an immutable profile; subsequent metadata edits never authorize access.
create function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.raw_user_meta_data->>'role' not in ('pencari','pemilik') or new.raw_user_meta_data->>'role' is null then raise exception 'Peran akun tidak valid'; end if;
 insert into public.users(id,email,role) values(new.id,new.email,new.raw_user_meta_data->>'role');
 return new;
end $$;
revoke all on function private.handle_new_user() from public;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
alter table public.users enable row level security;
alter table public.listings enable row level security;
alter table public.listing_analyses enable row level security;
alter table public.favorites enable row level security;
alter table public.wizard_drafts enable row level security;
alter table public.surveys enable row level security;
alter table public.applications enable row level security;
alter table public.messages enable row level security;
revoke all on all tables in schema public from anon,authenticated;
grant select on public.listings,public.listing_analyses to anon,authenticated;
grant select on public.users,public.surveys,public.applications,public.messages to authenticated;
grant insert,update on public.listings,public.listing_analyses to authenticated;
grant delete on public.listing_analyses to authenticated;
grant select,insert,update,delete on public.favorites,public.wizard_drafts to authenticated;
grant insert on public.surveys,public.applications,public.messages to authenticated;
grant usage on sequence public.listings_id_seq,public.messages_id_seq to authenticated;
create policy listings_read on public.listings for select to anon,authenticated using(status<>'draft' or owner_id=(select auth.uid()));
create policy listings_insert on public.listings for insert to authenticated with check(owner_id=(select auth.uid()) and (select private.account_role())='pemilik' and status in ('draft','available'));
create policy listings_update on public.listings for update to authenticated using(owner_id=(select auth.uid()) and status in ('draft','available')) with check(owner_id=(select auth.uid()) and status in ('draft','available'));
create policy analysis_read on public.listing_analyses for select to anon,authenticated using(exists(select 1 from public.listings l where l.id=listing_id));
create policy analysis_write on public.listing_analyses for all to authenticated using(exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=(select auth.uid()))) with check(exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=(select auth.uid())));
create policy favorites_own on public.favorites for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and (select private.account_role())='pencari' and exists(select 1 from public.listings l where l.id=listing_id and l.status<>'draft'));
create policy drafts_own on public.wizard_drafts for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and (select private.account_role())='pencari');
create policy surveys_read on public.surveys for select to authenticated using(seeker_id=(select auth.uid()) or exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=(select auth.uid())));
create policy applications_read on public.applications for select to authenticated using(seeker_id=(select auth.uid()) or exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=(select auth.uid())));
create policy surveys_insert on public.surveys for insert to authenticated with check(seeker_id=(select auth.uid()) and (select private.account_role())='pencari' and status='pending' and owner_note='' and exists(select 1 from public.listings l where l.id=listing_id and l.owner_id is not null and l.status='available') and time in ('09:00','10:00','13:00','15:00') and (date||'T'||time||':00+07:00')::timestamptz>now());
create policy applications_insert on public.applications for insert to authenticated with check(seeker_id=(select auth.uid()) and (select private.account_role())='pencari' and status='pending' and owner_note='' and exists(select 1 from public.listings l where l.id=listing_id and l.owner_id is not null and l.status='available') and start_date::date >= (now() at time zone 'Asia/Jakarta')::date);
create policy messages_read on public.messages for select to authenticated using(seeker_id=(select auth.uid()) or exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=(select auth.uid())));
create policy messages_insert on public.messages for insert to authenticated with check(sender_id=(select auth.uid()) and exists(select 1 from public.listings l where l.id=listing_id and l.owner_id is not null and ((seeker_id=(select auth.uid()) and (select private.account_role())='pencari' and l.status<>'draft') or (l.owner_id=(select auth.uid()) and exists(select 1 from public.messages m where m.listing_id=l.id and m.seeker_id=messages.seeker_id)))));
create policy profile_read on public.users for select to authenticated using(id=(select auth.uid()) or exists(select 1 from public.listings l where l.owner_id=users.id and l.status<>'draft') or exists(select 1 from public.surveys s join public.listings l on l.id=s.listing_id where s.seeker_id=users.id and l.owner_id=(select auth.uid())) or exists(select 1 from public.applications a join public.listings l on l.id=a.listing_id where a.seeker_id=users.id and l.owner_id=(select auth.uid())) or exists(select 1 from public.messages m join public.listings l on l.id=m.listing_id where (m.seeker_id=users.id and l.owner_id=(select auth.uid())) or (l.owner_id=users.id and m.seeker_id=(select auth.uid()))));
create function public.save_listing(p_id bigint,p_listing jsonb,p_analysis jsonb) returns bigint language plpgsql security invoker set search_path='' as $$
declare v_id bigint; v_owner uuid := auth.uid();
begin
 if v_owner is null or private.account_role()<>'pemilik' or p_listing->>'owner_id'<>v_owner::text then raise exception 'Akses ditolak'; end if;
 if p_id is null then
 insert into public.listings(owner_id,name,address,price,latitude,longitude,area,image,facilities,description,status,updated_at) values(v_owner,p_listing->>'name',p_listing->>'address',(p_listing->>'price')::bigint,(p_listing->>'latitude')::float8,(p_listing->>'longitude')::float8,(p_listing->>'area')::float8,p_listing->>'image',p_listing->>'facilities',p_listing->>'description',p_listing->>'status',p_listing->>'updated_at') returning id into v_id;
 else
 update public.listings set name=p_listing->>'name',address=p_listing->>'address',price=(p_listing->>'price')::bigint,latitude=(p_listing->>'latitude')::float8,longitude=(p_listing->>'longitude')::float8,area=(p_listing->>'area')::float8,image=p_listing->>'image',facilities=p_listing->>'facilities',description=p_listing->>'description',status=p_listing->>'status',updated_at=p_listing->>'updated_at' where id=p_id and owner_id=v_owner and status in ('draft','available') returning id into v_id;
 if v_id is null then raise exception 'Listing tidak dapat diubah'; end if;
 end if;
 if p_analysis is null then delete from public.listing_analyses where listing_id=v_id;
 else insert into public.listing_analyses values(v_id,p_analysis->>'modelVersion',p_analysis->>'inputFingerprint',p_analysis->>'analyzedAt',p_analysis::text) on conflict(listing_id) do update set model_version=excluded.model_version,input_fingerprint=excluded.input_fingerprint,analyzed_at=excluded.analyzed_at,result_json=excluded.result_json; end if;
 return v_id;
end $$;
revoke all on function public.save_listing(bigint,jsonb,jsonb) from public,anon;
grant execute on function public.save_listing(bigint,jsonb,jsonb) to authenticated;
-- Privileged transaction is private and explicitly verifies the caller and listing owner.
create function private.decide_request(p_kind text,p_id uuid,p_status text,p_note text) returns void language plpgsql security definer set search_path='' as $$
declare v_listing bigint; v_owner uuid; v_state text; v_listing_state text; v_date text; v_time text; v_now text := to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
begin
 if auth.uid() is null or private.account_role()<>'pemilik' or length(p_note)>2000 then raise exception 'Akses ditolak'; end if;
 if p_kind='surveys' then select listing_id into v_listing from public.surveys where id=p_id;
 elsif p_kind='applications' then select listing_id into v_listing from public.applications where id=p_id;
 else raise exception 'Jenis permintaan tidak valid'; end if;
 select owner_id,status into v_owner,v_listing_state from public.listings where id=v_listing for update;
 if v_owner is distinct from auth.uid() then raise exception 'Permintaan tidak ditemukan'; end if;
 if p_kind='surveys' then
 select status,date,time into v_state,v_date,v_time from public.surveys where id=p_id for update;
 if v_state<>'pending' or p_status not in ('confirmed','rejected') then raise exception 'Perubahan status tidak valid'; end if;
 if p_status='confirmed' and (v_date||'T'||v_time||':00+07:00')::timestamptz<=now() then raise exception 'Jadwal telah lewat'; end if;
 update public.surveys set status=p_status,owner_note=p_note,updated_at=v_now where id=p_id;
 else
 select status into v_state from public.applications where id=p_id for update;
 if v_state<>'pending' or p_status not in ('approved','rejected') then raise exception 'Perubahan status tidak valid'; end if;
 if p_status='approved' then
 if v_listing_state<>'available' then raise exception 'Ruko tidak lagi tersedia'; end if;
 update public.listings set status='reserved',updated_at=v_now where id=v_listing;
 update public.applications set status='rejected',owner_note='Ruko telah dipesan oleh pengajuan lain.',updated_at=v_now where listing_id=v_listing and id<>p_id and status='pending';
 end if;
 update public.applications set status=p_status,owner_note=p_note,updated_at=v_now where id=p_id;
 end if;
end $$;
revoke all on function private.decide_request(text,uuid,text,text) from public;
grant execute on function private.decide_request(text,uuid,text,text) to authenticated;
create function public.decide_request(p_kind text,p_id uuid,p_status text,p_note text) returns void language sql security invoker set search_path='' as $$ select private.decide_request(p_kind,p_id,p_status,p_note) $$;
revoke all on function public.decide_request(text,uuid,text,text) from public,anon;
grant execute on function public.decide_request(text,uuid,text,text) to authenticated;
